/**
 * Prints src/predictor/arith-tables.ts to stdout: the two lookup tables of arith.ts.
 *
 *   npx tsx scripts/arith-tables.ts > src/predictor/arith-tables.ts
 *
 * LOG2_TABLE[i] = floor(log2(1 + i / 4096) * 2^24) and EXP2_TABLE[i] = floor(2^(i / 4096) * 2^24).
 * These are the only transcendental values of the predictor; the generated file holds them as
 * literals so that every engine builds the same tables.
 */

const RB = 24;
const SIZE = 4096;
const WIDTH = 100;

const log2Table = (): number[] =>
  Array.from({ length: SIZE }, (_, i) => Math.floor(Math.log2(1 + i / SIZE) * 2 ** RB));

const exp2Table = (): number[] =>
  Array.from({ length: SIZE }, (_, i) => Math.floor(2 ** (i / SIZE) * 2 ** RB));

/** The declaration of one table, with the numbers filled into lines the way prettier lays them out. */
const declare = (name: string, values: number[]): string => {
  const lines: string[] = [];
  let line = '  ';
  for (const value of values) {
    const item = `${value},`;
    if (line.length > 2 && line.length + 1 + item.length > WIDTH) {
      lines.push(line);
      line = '  ';
    }
    line += (line.length > 2 ? ' ' : '') + item;
  }
  lines.push(line);
  return `export const ${name} = new Int32Array([\n${lines.join('\n')}\n]);\n`;
};

process.stdout.write(
  [
    '/**',
    ' * Generated by scripts/arith-tables.ts; do not edit.',
    ' *',
    ' * LOG2_TABLE[i] = floor(log2(1 + i / 4096) * 2^24).',
    ' * EXP2_TABLE[i] = floor(2^(i / 4096) * 2^24).',
    ' */',
    '',
    declare('LOG2_TABLE', log2Table()),
    declare('EXP2_TABLE', exp2Table()),
  ].join('\n')
);

export {};
